sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here

	var requestBody = request.body.data;
    var sys_id = requestBody.sys_id;
    var category = requestBody.category;
    var flowName = requestBody.flowName;

    if (!sys_id || !category) {
        response.setStatus(400);
        response.setBody({ error: "Missing required parameters: sys_id and category" });
        return;
    }

    var gr = new GlideRecord('cmdb_model'); // Table name
    // gr.addQuery('sys_id', sys_id); // Query condition
	gr.addEncodedQuery('product_catalog_itemISEMPTY^sys_idSTARTSWITH'+ sys_id);
    gr.query(); // Execute the query

    if (gr.next()) { // Check if the record exists
        gs.print("Record found with sys_id: " + gr.getValue('sys_id'));
        gs.print("Existing Field Value (name): " + gr.getValue('name'));

        var obj = new PublishToCatalogCustom();
        var productCatalogSysId = obj.createProductCatalog(gr, category, 'model_use_display_name', 'pc_software_cat_item',flowName);
        gs.log("From API" + 'pc_software_cat_item' +  flowName);
        gr.setValue('product_catalog_item', productCatalogSysId); // Update field value
        gr.update(); // Save the changes to the database

        response.setStatus(200);
        response.setBody({
            message: "Field 'product_catalog_item' updated successfully!",
            updated_sys_id: productCatalogSysId,
			success : true,
			status : "success"
        });
    } else {
        response.setStatus(404);
        response.setBody({ error: "No record found with the specified sys_id." });
    }


})(request, response);
